contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: drives c and asserts the distinguishing property
    function runTest(uint sendAmount) public {
        // precondition: sendAmount must be exactly MinDeposit and this contract must have enough ETH
        uint min = c.MinDeposit();
        require(sendAmount == min, "sendAmount must equal MinDeposit");
        require(address(this).balance >= sendAmount, "insufficient balance for test");

        // record balance before
        uint before = c.balances(address(this));

        // perform deposit of exactly MinDeposit
        c.Deposit{value: sendAmount}();

        // observe balance after
        uint after = c.balances(address(this));

        // On the original contract P deposits equal to MinDeposit are accepted and should increase recorded balance by sendAmount.
        // The mutant M (which uses > MinDeposit) will reject this deposit and thus not increase the recorded balance.
        assert(after == before + sendAmount);
    }

    // fallback to receive ETH for funding the test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving the contract
    // params: depositor address (must be this contract), deposit value
    function runTest(uint depositAmt) public {
        // ensure this contract can send the deposit
        require(address(this).balance >= depositAmt);

        address self = address(this);
        uint before = c.balances(self);
        uint minDep = c.MinDeposit();

        // perform the deposit call sending Ether
        c.Deposit{value: depositAmt}();

        uint after = c.balances(self);

        // Rule: balances increases exactly when depositAmt >= minDep
        // Expressed as: (after > before) == (depositAmt >= minDep)
        assert((after > before) == (depositAmt >= minDep));
    }

    // allow receiving Ether for funding deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v) public payable {
        require(address(this).balance >= v);
        uint before = address(c).balance;
        c.Deposit{value: v}();
        uint afterBal = address(c).balance;
        // On the original, deposits below MinDeposit do not increase c's ETH balance; deposits >= MinDeposit do.
        // This asserts that after - before > 0 implies v >= c.MinDeposit(), i.e. the contract only accepts (adds) ETH when v >= MinDeposit.
        assert( (afterBal > before) == (v >= c.MinDeposit()) );
    }
    receive() external payable {}
}

