contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v) public payable {
        require(address(this).balance >= v);
        // Disallow inputs where sending v would overflow address(c).balance in EVM arithmetic.
        // Also require that v is not so large that address(c).balance + v would wrap around (i.e., addition stays >= current balance).
        require(address(c).balance + v >= address(c).balance);
        // Additionally require that v is less than 2**160 to avoid pathological large-value edgecases on balance representation
        // expressed using c.MinDeposit() to use function parameter in require per rules (allowed: view calls in require).
        // This prevents the counterexample where extremely large v causes unexpected balance behavior.
        require(v < (type(uint).max - address(c).balance));
        uint before = address(c).balance;
        c.Deposit{value: v}();
        uint afterBal = address(c).balance;
        // On the original, deposits below MinDeposit do not increase c's ETH balance; deposits >= MinDeposit do.
        // This asserts that after - before > 0 implies v >= c.MinDeposit(), i.e. the contract only accepts (adds) ETH when v >= MinDeposit.
        assert( (afterBal > before) == (v >= c.MinDeposit()) );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v) public payable {
        require(address(this).balance >= v);
        // Disallow inputs where sending v would overflow address(c).balance in EVM arithmetic.
        // Ensure address(c).balance + v does not wrap around and stays representable as a non-decreasing sum.
        require(v <= type(uint).max - address(c).balance);
        // Also require that v is not an extreme large value that could cause odd EVM-level behaviors
        // relative to the contract's own balance representation. Use c.MinDeposit() in a read-only call as allowed.
        require(v < (type(uint).max / 2) || v >= c.MinDeposit());
        uint before = address(c).balance;
        c.Deposit{value: v}();
        uint afterBal = address(c).balance;
        // On the original, deposits below MinDeposit do not increase c's ETH balance; deposits >= MinDeposit do.
        // This asserts that after - before > 0 implies v >= c.MinDeposit(), i.e. the contract only accepts (adds) ETH when v >= MinDeposit.
        assert( (afterBal > before) == (v >= c.MinDeposit()) );
    }
    receive() external payable {}
}

