pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: depositor, depositAmt, withdrawAmt, otherAddr
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 withdrawAmt, address otherAddr) public {
        // keep addresses non-zero to be meaningful
        vm.assume(depositor != address(0));
        vm.assume(otherAddr != address(0));

        // bound depositAmt and withdrawAmt to reasonable ranges (<= 5 ether)
        depositAmt = bound(depositAmt, 0, 5 ether);
        withdrawAmt = bound(withdrawAmt, 0, 5 ether);

        // Fund depositor so they can send depositAmt
        vm.deal(depositor, depositAmt + 1 ether);

        // Make depositor send Deposit() with depositAmt
        vm.prank(depositor);
        if (depositAmt > 0) {
            // call Deposit payable
            (bool ok, ) = address(c).call{value: depositAmt}(abi.encodeWithSignature("Deposit()"));
            // allow both success and no-op; Deposit silently does nothing if below MinDeposit in reference
        } else {
            // zero value deposit allowed but will be ignored by logic; still call
            (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Deposit()"));
        }

        // Record old balance of depositor according to contract getter
        uint256 oldBal = c.balances(depositor);

        // Ensure caller has enough ETH to receive CashOut; contract must have funds to pay out.
        // To ensure contract has some balance to pay, we fund the contract by sending some ETH from this test
        // Only needed to allow CashOut to succeed when balances allow it.
        vm.deal(address(this), 5 ether);
        // send some ETH to contract to ensure liquidity
        (bool funded,) = address(c).call{value: 1 ether}("");
        require(funded);

        // Now attempt CashOut from depositor of withdrawAmt
        vm.prank(depositor);
        bool ok;
        try c.CashOut(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, the reference contract C satisfies: if oldBal >= withdrawAmt then balances[depositor] == oldBal - withdrawAmt
        // We assert that property (this will hold for the reference); the mutant (which changes Deposit guard) will allow inputs
        // where oldBal differs causing this assertion to fail for some fuzzed inputs.
        if (oldBal >= withdrawAmt) {
            assertTrue(c.balances(depositor) == (oldBal - withdrawAmt));
        } else {
            // If oldBal < withdrawAmt, CashOut must have done nothing; balances unchanged
            assertTrue(c.balances(depositor) == oldBal);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor (who sends deposits), depositor2 (another account),
    // depositAmt (amount to deposit by depositor), depositAmt2 (amount by depositor2),
    // withdrawAmt (amount to withdraw by depositor2 via CashOut)
    function testFuzz_property(address depositor, address depositor2, uint256 depositAmt, uint256 depositAmt2, uint256 withdrawAmt) public {
        // Keep addresses non-zero and distinct to avoid trivialities
        vm.assume(depositor != address(0));
        vm.assume(depositor2 != address(0));
        // allow same depositor as depositor2 — still admissible

        // Bound amounts to reasonable ETH-like ranges but keep wide so bug-triggering values are allowed
        depositAmt = bound(depositAmt, 0, 5 ether);
        depositAmt2 = bound(depositAmt2, 0, 5 ether);
        withdrawAmt = bound(withdrawAmt, 0, 5 ether);

        // Fund the depositor accounts so they can send deposits
        vm.deal(depositor, depositAmt);
        vm.deal(depositor2, depositAmt2 + withdrawAmt);

        // Make deposits from depositor and depositor2
        if (depositAmt > 0) {
            vm.prank(depositor);
            // call Deposit with depositAmt
            c.Deposit{value: depositAmt}();
        }
        if (depositAmt2 > 0) {
            vm.prank(depositor2);
            c.Deposit{value: depositAmt2}();
        }

        // Record sum of all balances by querying both keys (we fuzz two addresses)
        // This is a simple, admissible wide observation: the sum of balances at these addresses
        // (sufficient to detect difference because mutant may have skipped a deposit)
        uint256 sumBefore = c.balances(depositor) + c.balances(depositor2);

        // Now attempt CashOut by depositor2 of withdrawAmt
        vm.prank(depositor2);
        // wrap in try/catch to observe success/failure but we only assert on balances mapping
        bool ok;
        try c.CashOut(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After CashOut, sum of the two tracked balances
        uint256 sumAfter = c.balances(depositor) + c.balances(depositor2);

        // GENERAL RULE (single assert): For the correct contract, if CashOut succeeded then
        // the aggregate stored balances for these two accounts must have decreased by exactly withdrawAmt
        // if and only if depositor2 had at least withdrawAmt recorded in balances before the call.
        // We express a conservative invariant that must hold for the reference for all inputs:
        //    If CashOut returned ok==true then sumAfter + withdrawAmt == sumBefore.
        // The mutant (which rejects >= MinDeposit deposits) can cause depositor2's prior deposit to be missing
        // so CashOut may succeed in a way that makes this equality fail for some fuzzed inputs.

        if (ok) {
            // single assertion observing c's public getters
            assertTrue(sumAfter + withdrawAmt == sumBefore);
        } else {
            // If CashOut reverted, the mapping must be unchanged (conservative property): sumAfter == sumBefore
            assertTrue(sumAfter == sumBefore);
        }
    }
}
